use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioKitSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let reference=|id:&str,subset:&str|store::os_io::ArtifactRef{artifact_id:id.into(),dialect:store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:subset.into()}};SemioKitSnapshot{schema:f["schema"].as_str().unwrap().into(),types:vec![SemioKitType{id:f["typeId"].as_str().unwrap().into(),name:"Chair 世界".into(),category:"furniture".into()}],designs:vec![SemioKitDesign{id:f["designId"].as_str().unwrap().into(),name:"Design".into(),pieces:f["pieceIds"].as_array().unwrap().iter().enumerate().map(|(ordinal,id)|{let mut transform=SemioTransform::identity();transform.translation.x=ordinal as f64;SemioKitPiece{id:id.as_str().unwrap().into(),type_id:"chair".into(),transform}}).collect(),connections:vec![SemioKitConnection{id:f["connectionId"].as_str().unwrap().into(),connecting_piece_id:"left".into(),connecting_port:"a".into(),connected_piece_id:"right".into(),connected_port:"b".into()}]}],objects:f["objectChildIds"].as_array().unwrap().iter().map(|id|store::ArtifactChild::new(id.as_str().unwrap().into(),reference(id.as_str().unwrap(),"object"))).collect(),models:vec![store::ArtifactChild::new("model-one".into(),reference("model-one","model"))],properties:Some(store::ArtifactChild::new("value-one".into(),reference("value-one","value"))),representations:[store::LinkPin::Head,store::LinkPin::Checkpoint{id:f["checkpointId"].as_str().unwrap().into()},store::LinkPin::Snapshot{blob:store::BlobRef{hash:f["blobHash"].as_str().unwrap().into(),size:f["blobSize"].as_str().unwrap().parse().unwrap(),media_type:f["blobMediaType"].as_str().unwrap().into()}}].into_iter().enumerate().map(|(ordinal,pin)|store::ArtifactLink{target:reference(&format!("representation-{ordinal}"),"mesh"),role:"chair".into(),pin}).collect()}}
fn project(value:&SemioKitSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioKitSnapshot, semio_framework_value::ValueError>{SemioKitSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_kit_manual_native_child_and_link_fields_are_literal(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for id in f["literalChildIds"].as_array().unwrap(){let id=id.as_str().unwrap();let target=store::os_io::ArtifactRef{artifact_id:id.into(),dialect:store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"object".into()}};let child=store::ArtifactChild::<SemioObjectSnapshot>::new(id.into(),target.clone());let text=enc_child(&child);let restored:store::ArtifactChild<SemioObjectSnapshot>=dec_child(&text).unwrap();assert_eq!(restored.child_id,id);assert_eq!(restored.target,target);let mut bytes=Vec::new();write_child(&mut bytes,&child);let restored:store::ArtifactChild<SemioObjectSnapshot>=read_child(&mut store::ByteReader::new(&bytes)).unwrap();assert_eq!(restored.child_id,id);assert_eq!(restored.target,target);let link=store::ArtifactLink{target:target.clone(),role:"".into(),pin:store::LinkPin::Head};assert_eq!(dec_link(&enc_link(&link)).unwrap(),link);let mut bytes=Vec::new();write_link(&mut bytes,&link);assert_eq!(read_link(&mut store::ByteReader::new(&bytes)).unwrap(),link);}}

#[test]
fn sqlite_snapshot_semio_kit_design_foreign_keys_handles_all_link_pins_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));let mut value=fixture();value.properties=None;assert_eq!(restore(&project(&value)).unwrap(),value);assert_eq!(restore(&project(&SemioKitSnapshot::default())).unwrap(),SemioKitSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_kit_rejects_design_reference_identity_pin_shape_and_limits(){let original=project(&fixture());for change in 0..6{let mut db=original.clone();match change{0=>db.table_mut("semio_kit_connection").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>db.table_mut("semio_kit_piece").unwrap().rows[0].values[4]=SqliteValue::Integer(999),2=>db.table_mut("semio_kit_reference").unwrap().rows[0].values[2]=SqliteValue::Text("foreign.artifact".into()),3=>db.table_mut("semio_kit_representation").unwrap().rows[0].values[6]=SqliteValue::Text("unexpected".into()),4=>db.table_mut("semio_kit_blob").unwrap().rows[0].values[2]=SqliteValue::Text("18446744073709551616".into()),_=>db.table_mut("semio_kit_piece").unwrap().rows[0].values[2]=SqliteValue::Integer(99)}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioKitSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_kit_independent_connection_query_and_pin_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=db.query('SELECT a.native_id a,b.native_id b FROM semio_kit_connection JOIN semio_kit_piece a ON a.id=connecting_piece_id JOIN semio_kit_piece b ON b.id=connected_piece_id').get();if(r.a!=='left'||r.b!=='right'||db.query('SELECT size FROM semio_kit_blob').get().size!=='18446744073709551615')throw Error('design/wide blob');db.query(\"UPDATE semio_kit_representation SET checkpoint_id='independently edited' WHERE pin_kind='checkpoint'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.representations[1].pin=store::LinkPin::Checkpoint{id:"independently edited".into()};assert_eq!(restored,expected);}

#[test]
fn sqlite_snapshot_semio_kit_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioKitSnapshot,crate::standards::v1::subsets::kit::schema::mutations::SemioKitMutation>("s.stdio.semio.kit");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioKitSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"kit".into()};let db=(provider.export)("s.stdio.semio.kit",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.kit",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_kit_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let _v32=f32::from_bits(bits32);let mut s=fixture();s.designs[0].pieces[0].transform.translation.x=v;let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((r.designs[0].pieces[0].transform.translation.x).to_bits(),bits);assert_eq!(<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_kit_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_kit_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_kit_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"kit".into()};
    let provider=<SemioKitSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioKitSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}

#[test]
fn sqlite_snapshot_semio_kit_distinct_alias(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for alias in f["distinctAliases"].as_array().unwrap(){let mut s=fixture();s.objects[0].child_id=alias["childId"].as_str().unwrap().into();s.objects[0].target.artifact_id=alias["artifactId"].as_str().unwrap().into();let text=<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&s);let binary=<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&s);assert_eq!(<SemioKitSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap(),s);assert_eq!(<SemioKitSnapshot as store::ArtifactPack>::decode_pack(&binary).unwrap(),s);let db=project(&s);let row=&db.table("semio_kit_object_child").unwrap().rows[0];assert_eq!(row.text(3).unwrap(),alias["childId"].as_str().unwrap());assert_eq!(restore(&db).unwrap(),s);}}

#[test]
fn sqlite_snapshot_semio_kit_controlled_native_collection_materialization(){let mut s=fixture();s.types=(0..1024).map(|index|SemioKitType{id:if index==0{"chair".into()}else{format!("type-{index}")},name:format!("Type {index}"),category:"furniture".into()}).collect();for payload in [store::os_io::IoPayload::Binary(<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&s)),store::os_io::IoPayload::Text(<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&s))]{assert_eq!(SemioKitSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),s);let mut interior=false;let error=SemioKitSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::DecodeNative&&event.total==1024&&event.completed==256;interior|=cancel;!cancel},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.message.contains("cancel"),"{error}");assert!(SemioKitSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());assert!(SemioKitSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:10,..SqliteDatabaseLimits::default()})).is_err());assert!(SemioKitSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}}

#[test]
fn sqlite_snapshot_semio_kit_native_transform_words(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for word in f["float64Bits"].as_array().unwrap(){let bits=u64::from_str_radix(word.as_str().unwrap(),16).unwrap();let mut s=fixture();s.designs[0].pieces[0].transform.translation.x=f64::from_bits(bits);let text=<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&s);let parsed=<SemioKitSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap();assert_eq!(parsed.designs[0].pieces[0].transform.translation.x.to_bits(),bits);}}

#[test]
fn sqlite_snapshot_semio_kit_controlled_native_output(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let mut s=fixture();s.objects[0].child_id="x".repeat(f["nativeOutputBytes"].as_u64().unwrap() as usize);s.objects[0].target.artifact_id="remote!@/".into();for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&s))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");let mut interior=false;let error=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::EncodeNative&&event.total>65536&&event.completed>=65536&&event.completed<event.total;interior|=cancel;!cancel},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.message.contains("cancel"),"{error}");assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}}

#[test]
fn sqlite_snapshot_semio_kit_all_transform_fields_erased_word_state(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let words=f["transformBits"].as_array().unwrap();assert_eq!(words.len(),10);let provider=store::ArtifactCodec::bare::<SemioKitSnapshot,crate::standards::v1::subsets::kit::schema::mutations::SemioKitMutation>("s.stdio.semio.kit").snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"kit".into()};for offset in 0..words.len(){let mut s=fixture();let t=&mut s.designs[0].pieces[0].transform;for(index,field)in [&mut t.translation.x,&mut t.translation.y,&mut t.translation.z,&mut t.rotation.x,&mut t.rotation.y,&mut t.rotation.z,&mut t.rotation.w,&mut t.scale.x,&mut t.scale.y,&mut t.scale.z].into_iter().enumerate(){*field=f64::from_bits(u64::from_str_radix(words[(index+offset)%words.len()].as_str().unwrap(),16).unwrap());}for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioKitSnapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioKitSnapshot as store::ArtifactDsl>::print_dsl(&s))};let db=(provider.export)("s.stdio.semio.kit",&dialect,&expected,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.kit",&dialect,db,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,expected,"field word rotation {offset} {encoding:?}");}}}
